import React, { createContext, useContext, useState, useEffect } from 'react';
import { getObjetos, setObjetos, addObjeto, removeObjeto } from './localStorageUtils';

const DataContext = createContext();

export function DataProvider({ children }) {
  const [objetos, setObjetosState] = useState([]);

  // Carregar os objetos do Local Storage ao inicializar
  useEffect(() => {
    setObjetosState(getObjetos());
  }, []);

  // Função para adicionar um novo objeto
  const handleAddObjeto = (novoObjeto) => {
    addObjeto(novoObjeto);
    setObjetosState(getObjetos()); // Atualiza o estado após adicionar
  };

  // Função para remover um objeto
  const handleRemoveObjeto = (id) => {
    removeObjeto(id);
    setObjetosState(getObjetos()); // Atualiza o estado após remover
  };

  return (
    <DataContext.Provider value={{ objetos, handleAddObjeto, handleRemoveObjeto }}>
      {children}
    </DataContext.Provider>
  );
}

export function useData() {
  return useContext(DataContext);
}
